text:
#brandingHeader > img {
  inline-size: 45px;
  block-size: 45px;
}

#brandingHeader .branding-header-name {
  font-size: 1.3rem;
  font-weight: 500;
  padding-block-end: 2px;
}

#brandingHeader .branding-header-title {
  font-size: 2.8rem;
  font-weight: 200;
  letter-spacing: 1px;
}

.account-hub-first-run {
  &#brandingHeader {
    & h1 {
      align-self: center;
    }

    & > img {
      align-self: center;
      inline-size: 65px;
      block-size: 65px;
    }

    & .branding-header-title {
      font-size: 3.7rem;
      font-weight: 300;
      line-height: 100%;
    }

    & .branding-header-name {
      font-size: 1rem;
      font-weight: 400;
    }
  }
}
